from pathlib import Path
import re
root = Path(__file__).resolve().parent
marks = {
6: ('Counterproof', 'M0 0H6V8H10.5V13H6V24H0ZM24 0H18V11H13.5V16H18V24H24Z', 'Two opposed turnstiles bring independently supported accounts toward an interval that remains open.', 'It carries proof, rigor and refusal of blind trust through two separate supports and visibly unequal readings.', 'The opposed piers can read as an abstract H before the proof reference is understood.'),
7: ('Punched witness', 'M24 12A12 12 0 1 1 0 12A12 12 0 1 1 24 12ZM4 5V11H10V5ZM14 13V19H20V13Z', 'A solid counterstamp exposes two square readings, with their displacement preserved in the record.', 'It carries evidence and transparency by making the two perforations inspectable within one substantial ink mass.', 'The two apertures may suggest a button or a die, and the proof reference is indirect.'),
8: ('Inference', 'M0 0H9V7H0ZM15 0H24V7H15ZM0 10H24V14H0ZM6 17H18V24H6Z', 'Two separate premises sit above an inference rule and a single narrower conclusion.', 'It carries proof, transparency and rigor by exposing the structure supporting the conclusion.', 'Familiar inference notation may imply that independent accounts must resolve to agreement.'),
9: ('Gauge', 'M0 0H19V6H7V18H19V24H0ZM11 9H24V15H11Z', 'A separate specimen enters a solid reference jaw with its clearance left visible.', 'It carries evidence, rigor and refusal of blind trust by making acceptance relative to an explicit reference.', 'The jaw may read as an E or a mechanical fitting without the Crosscheck name.'),
10: ('Split tally', 'M0 19L19 0H24V5L5 24H0ZM0 0H5L10.5 5.5L5.5 10.5L0 5ZM13.5 18.5L18.5 13.5L24 19V24H19Z', 'Two broad tally cuts cross, with one interrupted so the crossing itself stays visible.', 'It carries transparency and refusal of blind trust by retaining two distinguishable accounts at their intersection.', 'The crossing can suggest rejection or a percentage sign, and crossed bands are familiar in other identities.')
}
for n,(name,path,*_) in marks.items():
    (root / f'mark-{n}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">\n  <path d="{path}" fill="currentColor" fill-rule="evenodd"/>\n</svg>\n')
marks = {4: ('Divided QED', re.search(r'd="([^"]+)"', (root/'mark-4.svg').read_text()).group(1), 'Two solid triangles reconstruct an end-of-proof square around a diagonal seam.', 'It carries proof and rigor through the compact square used to close a mathematical argument.', 'The divided square is generic and says little about independent checking or exposed assumptions.'), **marks}
def svg(n, size):
    name, path, *_ = marks[n]
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="{size}" height="{size}" aria-hidden="true"><path d="{path}" fill="currentColor" fill-rule="evenodd"/></svg>'
css = '''
:root{color-scheme:light;--paper:#f8f7f4;--ink:#18191b;--rule:#7d808a;--link:#2a5a9e}
*{box-sizing:border-box}html{scroll-behavior:smooth;scrollbar-color:var(--rule) var(--paper)}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.5 Georgia,'Times New Roman',serif}main{max-width:1160px;margin:auto;padding:44px 40px 32px}h1,h2,p,figure{margin:0}h1{font-size:42px;line-height:1.12;font-weight:400;letter-spacing:-.025em}h2{font-size:28px;line-height:1.2;font-weight:400;letter-spacing:-.015em}header{padding-bottom:30px}header>p{max-width:68ch;margin-top:15px}nav{display:flex;flex-wrap:wrap;gap:8px 22px;margin-top:20px}a{color:var(--link);text-underline-offset:3px}a:hover{color:#153c74}a:focus-visible{outline:2px solid var(--link);outline-offset:5px}::selection{color:var(--ink);background:#f8eab4}nav,.file,figcaption,.label,footer{font:13px/1.5 'Public Sans','Helvetica Neue',Arial,sans-serif}section{border-top:1px solid var(--rule);padding:24px 0 28px;scroll-margin-top:20px}.heading{display:flex;align-items:baseline;justify-content:space-between;gap:16px}.heading a{white-space:nowrap}.specimens{display:grid;grid-template-columns:1fr 1fr;gap:44px;margin:24px 0}.sizes{display:grid;grid-template-columns:40px 80px 160px;gap:30px;align-items:end}figure{display:flex;flex-direction:column;gap:12px}svg{display:block;flex:none}figcaption,.label{color:#4f535b}.lockups{display:flex;flex-direction:column;justify-content:flex-end;gap:24px}.lockup{display:flex;align-items:center;gap:12px;font-size:28px;line-height:1.2;letter-spacing:-.015em;white-space:nowrap}.inverse{background:var(--ink);color:var(--paper);padding:20px 22px}.inverse .label{display:block;color:var(--paper);margin-top:12px}.study{border-top:1px solid #b6b8be;padding-top:20px}.study .lockup{font-size:24px;gap:10px}.study-title{font-size:28px;line-height:1.2;letter-spacing:-.02em;margin-top:12px}.notes{display:grid;grid-template-columns:1fr 1fr 1fr;gap:28px;margin-top:24px}.notes p{font-size:15px;line-height:1.5}.notes .label{display:block;margin-bottom:4px;color:var(--ink)}footer{border-top:1px solid var(--rule);padding-top:18px;color:#4f535b}footer p+p{margin-top:8px}
@media(max-width:800px){main{padding:30px 24px}.specimens{grid-template-columns:1fr;gap:24px}.sizes{gap:32px}.lockups{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:24px}.notes{gap:20px}.study-title{font-size:26px}}
@media(max-width:520px){main{padding:28px 20px}h1{font-size:34px}h2{font-size:25px}.specimens{margin:24px 0}.sizes{grid-template-columns:32px 72px 160px;gap:20px}.lockups{display:flex;align-items:stretch;gap:20px}.inverse{padding:18px 20px}.notes{grid-template-columns:1fr;gap:14px}.notes p{font-size:16px}.study-title{font-size:27px}.heading{align-items:flex-start}.file{padding-top:4px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{main{padding:0}section{break-inside:avoid}.inverse{print-color-adjust:exact;-webkit-print-color-adjust:exact}}
'''
html = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>Crosscheck marks · round 2</title><style>{css}</style></head><body><main>
<header><h1>Crosscheck marks, round 2</h1><p>Five new marks for independent checking and visible evidence, beside the unchanged divided QED square. All use solid ink; none represents an evidence grade.</p><p>Recommended: <a href="#mark-6">Counterproof</a>. Runner-up: <a href="#mark-7">Punched witness</a>. <a href="NOTES-round2.md">Read the concepts, scores and render notes.</a></p><nav aria-label="Compare marks">'''
html += ''.join(f'<a href="#mark-{n}">{n} · {m[0]}</a>' for n,m in marks.items()) + '</nav></header>\n'
for n,(name,path,idea,convictions,risk) in marks.items():
    html += f'<section aria-labelledby="mark-{n}"><div class="heading"><h2 id="mark-{n}">{n}. {name}</h2><a class="file" href="mark-{n}.svg">SVG file</a></div>\n<div class="specimens"><div class="sizes">'
    html += ''.join(f'<figure aria-label="{name} at {size} pixels">{svg(n,size)}<figcaption>{size}px</figcaption></figure>' for size in (24,64,160))
    html += f'</div><div class="lockups"><div class="lockup">{svg(n,24)}<span>Crosscheck</span></div><div class="inverse"><div class="lockup">{svg(n,24)}<span>Crosscheck</span></div><span class="label">Paper on ink</span></div></div></div>\n'
    html += f'<div class="study"><div class="lockup">{svg(n,22)}<span>Crosscheck</span></div><p class="study-title">EVerest OCPP lib: a formal study</p></div>\n'
    html += f'<div class="notes"><p><span class="label">Idea</span>{idea}</p><p><span class="label">Convictions</span>{convictions}</p><p><span class="label">Risk</span>{risk}</p></div></section>\n'
html += '<footer><p>24, 64 and 160px specimens are shown at their actual CSS dimensions. Study marks are 22px. Lockups use Georgia; labels use Public Sans when installed, with a system sans fallback.</p><p>Round 1 files remain on disk. Mark 4 is unchanged. <a href="NOTES-round2.md">Round 2 notes</a> · <a href="NOTES.md">Round 1 notes</a></p></footer></main></body></html>\n'
(root/'index.html').write_text(html)
